    /* notification style */

/* ===== NOTIFICATION BELL STYLES ===== */

.notification-bell-wrapper {
  display: inline-block;
}

/* Main Bell Container */
.nav-link {
  cursor: pointer;
  padding: 0;
  margin: 0;
  background: transparent;
  transition: all 0.3s ease;
}

.bell-container {
  position: relative;
  padding: 5px;
  border-radius: 50%;
  background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
  transition: all 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
}

.bell-container:hover {
  background: linear-gradient(135deg, #ffffff 0%, #e2e8f0 100%);
  transform: scale(1.08);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.12);
}

.bell-container:active {
  transform: scale(0.96);
}

/* Bell SVG Styling */
.bell-svg {
  fill: none;
  stroke: #64748b;
  stroke-width: 1.2;
  transition: all 0.3s ease;
  display: block;
}

.bell-container:hover .bell-svg {
  stroke: #3b82f6;
  filter: drop-shadow(0 2px 4px rgba(59, 130, 246, 0.3));
  animation: gentleRing 0.6s ease-in-out;
}

.bell-hover {
  background: linear-gradient(135deg, #ffffff 0%, #e2e8f0 100%);
  transform: scale(1.08);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.12);
}

.bell-hover .bell-svg {
  stroke:  #eb0707;;
  animation: gentleRing 0.6s ease-in-out;
}

/* Gentle ring animation */
@keyframes gentleRing {
  0% { transform: rotate(0deg); }
  15% { transform: rotate(12deg); }
  30% { transform: rotate(-10deg); }
  45% { transform: rotate(8deg); }
  60% { transform: rotate(-6deg); }
  75% { transform: rotate(4deg); }
  85% { transform: rotate(-2deg); }
  100% { transform: rotate(0deg); }
}

/* ===== PREMIUM BADGE DESIGN ===== */
.notification-badge {
  position: absolute;
  top: -7px;
  right: -12px;
  z-index: 10;
}

.badge-number {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  background: linear-gradient(135deg, #ef4444 0%, #dc2626 50%, #b91c1c 100%);
  color: white;
  font-size: 11px;
  font-weight: 800;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  border-radius: 20px;
  letter-spacing: 0.3px;
  box-shadow: 0 2px 8px rgba(239, 68, 68, 0.4);
  backdrop-filter: blur(2px);
  transition: all 0.2s ease;
  z-index: 2;
}

/* Badge hover effect */
.bell-container:hover .badge-number {
  transform: scale(1.12);
  box-shadow: 0 3px 12px rgba(239, 68, 68, 0.6);
  background: linear-gradient(135deg, #f97316 0%, #ef4444 50%, #dc2626 100%);
}

/* Badge pulse ring */
.badge-pulse {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 100%;
  min-width: 20px;
  min-height: 20px;
  background: rgba(239, 68, 68, 0.6);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  animation: badgePulse 1.8s infinite;
  z-index: 1;
}

/* Pulse animation keyframes */
@keyframes badgePulse {
  0% {
    transform: translate(-50%, -50%) scale(0.8);
    opacity: 0.8;
  }
  70% {
    transform: translate(-50%, -50%) scale(1.4);
    opacity: 0;
  }
  100% {
    transform: translate(-50%, -50%) scale(0.8);
    opacity: 0;
  }
}

/* Initial badge pop animation */
@keyframes badgePop {
  0% {
    transform: scale(0);
    opacity: 0;
  }
  60% {
    transform: scale(1.2);
  }
  100% {
    transform: scale(1);
    opacity: 1;
  }
}

.badge-number {
  animation: badgePop 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

/* Optional: Shimmer effect on badge when new notification arrives */
@keyframes badgeShimmer {
  0% {
    background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
  }
